<?php session_start(); require '../includes/db.php'; $user=$_POST['username']??''; $pass=$_POST['password']??''; $st=$pdo->prepare("SELECT * FROM admins WHERE username=?"); $st->execute([$user]); $admin=$st->fetch(); if($admin && password_verify($pass, $admin['password_hash'])){ $_SESSION['admin']=true; header('Location: dashboard.php'); exit; } else { header('Location: index.php?error=1'); exit; }
